/* ============ RESET / BASE ============ */
*,*::before,*::after{ box-sizing:border-box; -webkit-tap-highlight-color:transparent; }
html,body{ height:100%; margin:0; overflow:hidden; background:#04080b; }
body{
  position:fixed; inset:0; width:100%; height:100%;
  font-family: ui-rounded,"SF Pro Rounded",-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;
  color:#eaf6f8; touch-action:none; overscroll-behavior:none;
  user-select:none; -webkit-user-select:none; -webkit-touch-callout:none;
}
button{ font:inherit; color:inherit; border:0; background:none; padding:0; cursor:pointer; touch-action:manipulation; }
p,h1,h2,h3{ margin:0; }
svg{ display:block; }
.sprite{ position:absolute; width:0; height:0; overflow:hidden; }
.ic{ width:1em; height:1em; fill:none; stroke:currentColor; stroke-width:1.8; stroke-linecap:round; stroke-linejoin:round; flex:none; }
.ic.fill{ fill:currentColor; stroke:none; }

:root{
  --ink:#eaf6f8; --muted:#89a3ae; --dim:#54707c;
  --panel:#0b1921; --panel2:#0f232d; --line:#1b3541;
  --orange:#ff8a3d; --orange2:#ffb066; --teal:#38e0c0; --teal2:#8dfbe4;
  --red:#ff5670; --gold:#ffd166; --mono: ui-monospace,"SF Mono",Menlo,Consolas,monospace;
}

/* ============ APP SHELL ============ */
#app{
  position:relative; width:100%; height:100vh; height:100dvh; max-width:480px;
  margin:0 auto; overflow:hidden; background:#070d12;
  display:flex; flex-direction:column;
}
.bg{ position:absolute; inset:0; overflow:hidden; pointer-events:none; }
.bg-glow{ position:absolute; border-radius:50%; filter:blur(60px); opacity:.5; }
.bg-glow.g1{ width:70%; aspect-ratio:1; left:-25%; top:-18%; background:#0d5b5a; }
.bg-glow.g2{ width:80%; aspect-ratio:1; right:-35%; bottom:-12%; background:#5a2c12; opacity:.45; }
.bg-grid{ position:absolute; inset:0; opacity:.35;
  background-image:linear-gradient(#ffffff06 1px,transparent 1px),linear-gradient(90deg,#ffffff06 1px,transparent 1px);
  background-size:34px 34px; mask-image:radial-gradient(120% 80% at 50% 40%,#000 20%,transparent 80%); }

.screen{ position:absolute; inset:0; display:flex; flex-direction:column; min-height:0; }
.hidden{ display:none !important; }

/* ============ HUD ============ */
.hud{
  position:relative; z-index:5; flex:0 0 auto; display:flex; align-items:center; justify-content:space-between;
  gap:8px; padding:calc(8px + env(safe-area-inset-top)) 13px 6px;
}
.brand{ display:flex; align-items:center; gap:8px; min-width:0; }
.logo{
  width:30px; height:30px; border-radius:10px; display:grid; place-items:center; font-size:17px; color:#231006;
  background:linear-gradient(145deg,#ffb066,#ff6a2e 60%,#ef4a1c);
  box-shadow:0 5px 16px #ff7a2e55, inset 0 1px 0 #ffe3c9;
}
.logo .ic{ width:17px; height:17px; stroke-width:2.1; }
.brand-txt b{ display:block; font-size:15px; line-height:1; letter-spacing:.16em; font-weight:800; }
.brand-txt span{ display:block; font:7px/1 var(--mono); letter-spacing:.2em; color:var(--muted); margin-top:4px; }
.hud-right{ display:flex; align-items:center; gap:6px; }
.chip{
  display:flex; align-items:center; gap:5px; height:27px; padding:0 9px; border-radius:9px;
  background:#0c1a22cc; border:1px solid #1e3945; color:#cfe3e9; font:600 10px/1 var(--mono); letter-spacing:.06em;
  box-shadow:inset 0 1px 0 #ffffff08;
}
.chip.money{ color:var(--gold); font-size:11px; }
.chip.money .ic{ width:13px; height:13px; stroke-width:2; }
.chip .dot{ width:5px; height:5px; border-radius:50%; background:var(--teal); box-shadow:0 0 8px var(--teal); animation:blink 2.4s infinite; }
@keyframes blink{ 0%,100%{opacity:1} 50%{opacity:.3} }
.icon-btn{
  width:29px; height:29px; border-radius:9px; display:grid; place-items:center;
  background:#0c1a22cc; border:1px solid #1e3945; color:#a9c1ca;
}
.icon-btn:active{ transform:scale(.94); }

/* ============ CUSTOMER ============ */
.customer-bar{
  position:relative; z-index:4; flex:0 0 auto; display:flex; gap:9px; align-items:flex-start;
  padding:5px 13px 4px;
}
.customer-bar.in .avatar{ animation:popIn .45s cubic-bezier(.2,1.4,.5,1) both; }
.customer-bar.in .speech{ animation:slideIn .4s .05s both; }
@keyframes popIn{ from{ transform:scale(.6) translateY(8px); opacity:0 } }
@keyframes slideIn{ from{ transform:translateX(14px); opacity:0 } }
.avatar{
  width:48px; height:48px; flex:0 0 48px; border-radius:15px; overflow:hidden;
  background:#10242d; border:1px solid #294552; box-shadow:0 4px 12px #0007;
}
.avatar svg{ width:100%; height:100%; display:block; }
.speech{
  position:relative; flex:1; min-width:0; padding:6px 9px 7px;
  background:linear-gradient(180deg,#10232d,#0b1921); border:1px solid #1e3945; border-radius:4px 14px 14px 14px;
  box-shadow:0 6px 18px #0004, inset 0 1px 0 #ffffff08;
}
.speech::before{
  content:''; position:absolute; left:-6px; top:0; width:10px; height:10px;
  background:#10232d; border-left:1px solid #1e3945; border-bottom:1px solid #1e3945;
  transform:skewY(38deg); border-radius:0 0 0 2px;
}
.speech-top{ display:flex; align-items:baseline; gap:6px; }
.speech-top b{ font-size:11.5px; letter-spacing:.01em; }
.speech-top span{ font:8px/1 var(--mono); color:var(--muted); letter-spacing:.06em; text-transform:uppercase; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.speech p{
  font-size:10.5px; line-height:1.32; color:#c4d9df; margin:3px 0 5px;
  display:-webkit-box; -webkit-line-clamp:2; -webkit-box-orient:vertical; overflow:hidden;
}
.patience-row{ display:flex; align-items:center; gap:6px; }
.hearts{ display:flex; gap:2px; color:var(--red); }
.hearts .ic{ width:8px; height:8px; }
.hearts .off{ color:#2a3c44; }
.patience{ position:relative; flex:1; height:3px; border-radius:2px; background:#1b2f38; overflow:hidden; }
.patience i{ display:block; height:100%; width:100%; border-radius:2px; background:linear-gradient(90deg,#38e0c0,#8dfbe4); transition:background .3s; }
.patience.low i{ background:linear-gradient(90deg,#ff8a3d,#ffd166); }
.patience.crit i{ background:linear-gradient(90deg,#ff5670,#ff8a3d); animation:pulseBar .7s infinite; }
@keyframes pulseBar{ 50%{ opacity:.45 } }

/* ============ BENCH / MAT ============ */
.bench{ position:relative; z-index:3; flex:1 1 auto; min-height:0; display:flex; flex-direction:column; padding:2px 11px 0; }
.mat{
  position:absolute; left:8px; right:8px; top:0; bottom:82px; border-radius:22px;
  background:
    radial-gradient(90% 60% at 50% 0%,#143039 0%,transparent 60%),
    linear-gradient(180deg,#0c2029,#091820 65%,#071219);
  border:1px solid #193541; box-shadow:inset 0 2px 0 #ffffff07, inset 0 -20px 40px #0006, 0 18px 40px #0008;
  overflow:hidden;
}
.mat::before{
  content:''; position:absolute; inset:0; opacity:.5;
  background-image:linear-gradient(#ffffff07 1px,transparent 1px),linear-gradient(90deg,#ffffff07 1px,transparent 1px);
  background-size:22px 22px;
  mask-image:radial-gradient(90% 80% at 50% 40%,#000,transparent 85%);
}
.mat::after{
  content:''; position:absolute; inset:8px; border-radius:16px; border:1px dashed #ffffff0d;
}
.mat-mark{
  position:absolute; right:14px; bottom:9px; font:800 22px/1 var(--mono); letter-spacing:.14em;
  color:#ffffff07; transform:rotate(-90deg) translateX(100%); transform-origin:right bottom;
}
.mat-rule{ position:absolute; left:12px; bottom:12px; width:46px; height:3px; border-radius:2px;
  background:repeating-linear-gradient(90deg,#ff8a3d55 0 3px,transparent 3px 6px); opacity:.6; }

.stage{ position:relative; flex:1 1 auto; min-height:0; display:flex; align-items:center; justify-content:center; padding:9px 0 6px; z-index:2; }
.phone-wrap{ position:relative; height:min(100%,372px); aspect-ratio:.492; flex:0 0 auto; z-index:3; }
.phone-wrap::after{ content:''; position:absolute; left:4%; right:4%; bottom:-10px; height:14px; border-radius:50%; background:#000; filter:blur(7px); opacity:.7; }

/* ============ PHONE ============ */
.phone{
  position:absolute; inset:0; border-radius:15%/7.4%;
  background:linear-gradient(152deg,#82969d 0%,#2d3d44 14%,#101b20 48%,#3a4d55 88%,#0b1317 100%);
  box-shadow:0 24px 44px #000b, 0 0 0 1px #05090b, inset 0 1px 0 #ffffff33, inset 0 -1px 0 #ffffff18;
  transition:box-shadow .3s;
}
.phone::after{
  content:''; position:absolute; inset:2.6%; border-radius:13.5%/6.7%; background:#04090c;
  box-shadow:inset 0 0 0 1px #ffffff0d;
}
.phone-frame{ position:absolute; inset:0; border-radius:inherit; pointer-events:none; z-index:8; }
.phone-frame::before{
  content:''; position:absolute; left:-1.5px; top:20%; width:2.5px; height:8%; border-radius:2px; background:#42555c;
  box-shadow:0 34px 0 #42555c, 0 52px 0 #42555c;
}
.phone-frame::after{ content:''; position:absolute; right:-1.5px; top:27%; width:2.5px; height:13%; border-radius:2px; background:#42555c; }

.interior{
  position:absolute; inset:3.4%; border-radius:12.6%/6.2%; overflow:hidden; z-index:1;
  background:radial-gradient(120% 90% at 50% 0%,#0e2527,#060f12 72%);
  opacity:0; transition:opacity .3s .15s;
}
.phone.open .interior, .phone.reassembling .interior, .phone.screen-gone .interior{ opacity:1; }

.board{
  position:absolute; left:6%; right:6%; top:3.5%; bottom:6.5%; border-radius:6px;
  background:linear-gradient(168deg,#0c2a24,#061a17 55%,#0a2420);
  border:1px solid #1c4a40; box-shadow:inset 0 0 24px #000b, 0 0 0 1px #0008;
  overflow:hidden;
}
.board::before{
  content:''; position:absolute; inset:0; opacity:.8;
  background:
    repeating-linear-gradient(90deg,transparent 0 8px,#2f7a6822 8px 9px),
    repeating-linear-gradient(0deg,transparent 0 12px,#2f7a6818 12px 13px);
  mask-image:linear-gradient(160deg,#000,transparent 85%);
}
.board::after{
  content:''; position:absolute; left:6%; top:46%; width:34%; height:1px; background:linear-gradient(90deg,#c9a45a99,transparent);
  box-shadow:0 3px 0 #c9a45a55, 12px 6px 0 #c9a45a33, 3px 9px 0 #c9a45a44;
}
.chip{ position:absolute; border-radius:2px; background:linear-gradient(145deg,#243236,#0b1214); border:1px solid #33474c; box-shadow:inset 0 1px 0 #ffffff14, 0 1px 3px #0008; }
.chip.c1{ left:48%; top:7%; width:30%; height:11%; }
.chip.c2{ left:10%; top:24%; width:24%; height:8%; }
.chip.c3{ left:52%; top:20%; width:18%; height:7%; }
.chip.c4{ left:12%; top:76%; width:22%; height:9%; }
.trace{ position:absolute; height:1px; background:linear-gradient(90deg,transparent,#d3ac5f88,transparent); }
.trace.t1{ left:20%; top:34%; width:50%; transform:rotate(9deg); }
.trace.t2{ left:28%; top:56%; width:42%; transform:rotate(-14deg); }
.chassis-label{ position:absolute; left:0; right:0; bottom:2%; text-align:center; font:4px/1 var(--mono); letter-spacing:.18em; color:#4d7a72; opacity:.9; }

/* parts */
.part{ position:absolute; pointer-events:none; transition:opacity .25s, transform .3s, box-shadow .25s; }
.part.battery{
  left:15%; top:29%; width:70%; height:33%; border-radius:4px;
  background:linear-gradient(100deg,#93a5a7 0%,#e6efef 16%,#b7c7c8 48%,#8ba0a2 78%,#c7d5d5 100%);
  border:1px solid #647b7e; box-shadow:inset 0 1px 0 #ffffffcc, 0 3px 8px #0009;
  display:flex; align-items:center; justify-content:center;
}
.part.battery::before{ content:''; position:absolute; left:5%; top:7%; bottom:7%; width:2px; background:#6f8689; border-radius:2px; }
.part.battery::after{ content:''; position:absolute; left:9%; right:9%; top:50%; height:1px; background:#7e9396; opacity:.5; }
.batt-cell{ font:700 9px/1 var(--mono); color:#31464a; letter-spacing:.02em; display:flex; flex-direction:column; align-items:center; gap:2px; }
.batt-cell span{ font:5px/1 var(--mono); letter-spacing:.12em; opacity:.7; }
.batt-bolt{ position:absolute; left:10%; top:14%; font-size:14px; line-height:1; color:#31464a; font-weight:800; }
.batt-flex{ position:absolute; right:9%; top:-7%; width:20%; height:8%; background:linear-gradient(90deg,#8a6a2f,#ffd166,#8a6a2f); border-radius:2px 2px 0 0; box-shadow:0 0 0 1px #5b4419; }
.batt-warn{ position:absolute; right:6%; bottom:8%; font:4.5px/1 var(--mono); letter-spacing:.1em; color:#4d6467; }
.part.battery.loose{ transform:translateY(-4px) rotate(-.6deg); box-shadow:0 8px 14px #0009; }

.part.camera{
  left:7%; top:5%; width:40%; height:13%; border-radius:5px;
  background:linear-gradient(145deg,#3a4f56,#101b20 60%,#22333a); border:1px solid #47636c;
  box-shadow:inset 0 1px 0 #ffffff1c, 0 3px 7px #0009;
  display:flex; align-items:center; justify-content:space-evenly;
}
.part.camera i{ width:33%; aspect-ratio:1; border-radius:50%; background:radial-gradient(circle at 34% 28%,#b9e9f5,#1d5a6c 42%,#040b0e 74%); border:1.5px solid #081216; box-shadow:0 0 0 1px #557079, inset 0 0 4px #000; }
.part.camera b{ position:absolute; right:3%; bottom:2%; font:4px/1 var(--mono); color:#8fb2bb; }

.part.speaker{
  left:54%; top:6.5%; width:38%; height:5.5%; border-radius:3px;
  background:linear-gradient(#2c3d42,#0d181c); border:1px solid #3a525a;
  display:flex; align-items:center; justify-content:space-evenly; padding:0 4%;
}
.part.speaker i{ width:7%; height:55%; border-radius:1px; background:#7a929a; opacity:.55; }
.part.port{
  left:36%; bottom:2%; width:28%; height:3.4%; border-radius:3px;
  background:linear-gradient(#4c6067,#16242a); border:1px solid #5d757d;
  display:flex; align-items:center; justify-content:center;
}
.part.port i{ width:62%; height:40%; border-radius:2px; background:#020608; box-shadow:inset 0 1px 0 #ffffff22; }
.part.display-flex{ left:38%; top:5.5%; width:16%; height:3.5%; background:linear-gradient(90deg,#8a6a2f,#ffd166,#8a6a2f); border-radius:1px; opacity:.9; }
.part.focus{ box-shadow:0 0 0 1px #38e0c0aa, 0 0 16px #38e0c055, inset 0 1px 0 #ffffffcc; }
.part.removed{ opacity:0 !important; transform:scale(.92); pointer-events:none; }
.part.installed{ animation:partIn .45s cubic-bezier(.2,1.5,.4,1); }
@keyframes partIn{ 0%{ transform:scale(1.14); filter:brightness(1.7) } 100%{ transform:scale(1); filter:none } }

/* slot outlines */
.slot-outline{
  position:absolute; border-radius:4px; border:1px dashed #38e0c077; background:#38e0c00d;
  opacity:0; pointer-events:none; transition:opacity .2s; display:grid; place-items:center;
}
.slot-outline span{ font:5px/1 var(--mono); letter-spacing:.16em; color:#8dfbe4cc; }
.slot-outline[data-slot="battery"]{ left:15%; top:29%; width:70%; height:33%; }
.slot-outline[data-slot="camera"]{ left:7%; top:5%; width:40%; height:13%; }
.slot-outline[data-slot="speaker"]{ left:54%; top:6.5%; width:38%; height:5.5%; }
.slot-outline[data-slot="port"]{ left:36%; bottom:2%; width:28%; height:3.4%; }
.slot-outline.screen-slot{ inset:1.5%; border-radius:11%/5.5%; }
.slot-outline.active{ opacity:1; animation:slotPulse 1.4s infinite; }
.slot-outline.near{ opacity:1; background:#38e0c022; border-style:solid; box-shadow:0 0 18px #38e0c055; }
@keyframes slotPulse{ 50%{ border-color:#8dfbe4; background:#38e0c018 } }

/* ============ SCREEN ============ */
.screen-layer{
  position:absolute; inset:3.4%; border-radius:12.6%/6.2%; overflow:hidden; z-index:2;
  background:#000; box-shadow:inset 0 0 0 1px #ffffff14, 0 1px 10px #0009;
  transition:opacity .45s cubic-bezier(.3,.8,.3,1), transform .45s cubic-bezier(.3,.8,.3,1), visibility .45s;
  will-change:opacity, transform;
}
.wallpaper{
  position:absolute; inset:0;
  background:
    radial-gradient(90% 55% at 16% 6%,#ff8a3d88,transparent 55%),
    radial-gradient(80% 50% at 92% 88%,#38e0c077,transparent 58%),
    radial-gradient(70% 40% at 60% 40%,#5a3fd466,transparent 65%),
    linear-gradient(165deg,#1a2b4d,#0b1526 55%,#1a0f2a);
}
.wallpaper::after{
  content:''; position:absolute; inset:-20% -30%;
  background:conic-gradient(from 210deg at 50% 50%,transparent,#38e0c01a,transparent 35%,#ff8a3d1a,transparent 70%);
  filter:blur(10px);
}
.statusbar{
  position:absolute; top:3.5%; left:7%; right:7%; display:flex; align-items:center; justify-content:space-between;
  font:600 5.5px/1 var(--mono); color:#fff; letter-spacing:.02em; z-index:3;
}
.sb-icons{ display:flex; align-items:center; gap:2.5px; }
.sb-icons i{ display:block; background:#fff; }
.sb-icons .sig{ width:7px; height:4.5px; clip-path:polygon(0 100%,18% 100%,18% 70%,0 70%,0 100%,32% 100%,32% 50%,50% 50%,50% 100%,64% 100%,64% 30%,82% 30%,82% 100%,100% 100%,100% 0,100% 100%); }
.sb-icons .wifi{ width:5px; height:4.5px; clip-path:polygon(50% 100%,0 30%,50% 0,100% 30%); }
.sb-icons .batt{ width:8px; height:4.5px; border-radius:1px; box-shadow:inset 0 0 0 1px #fff; background:none; position:relative; }
.sb-icons .batt::after{ content:''; position:absolute; inset:1px 40% 1px 1px; background:#fff; border-radius:.5px; }

.lock-screen{ position:absolute; inset:0; display:flex; flex-direction:column; align-items:center; justify-content:center; z-index:2; color:#fff; padding-top:6%; }
.lock-date{ font:600 5px/1 var(--mono); letter-spacing:.14em; opacity:.8; }
.lock-time{ font:700 30px/1 -apple-system,"Segoe UI",sans-serif; letter-spacing:-.03em; margin-top:3px; text-shadow:0 2px 18px #0006; }
.lock-note{
  margin-top:13%; width:82%; display:flex; align-items:center; gap:5px; padding:5px 6px;
  background:#ffffff1c; border:1px solid #ffffff24; border-radius:7px; backdrop-filter:blur(4px);
}
.note-dot{ width:10px; height:10px; border-radius:3px; background:linear-gradient(145deg,#ffb066,#ff5d2e); flex:none; }
.lock-note b{ display:block; font-size:5.5px; }
.lock-note small{ display:block; font-size:4.5px; opacity:.7; margin-top:1px; }

.home-screen{ position:absolute; inset:0; z-index:2; display:none; flex-direction:column; padding:9% 8% 5%; }
.home-time{ font:700 10px/1 -apple-system,"Segoe UI",sans-serif; color:#fff; text-shadow:0 1px 6px #0007; margin-bottom:8%; }
.app-grid{ display:grid; grid-template-columns:repeat(4,1fr); gap:7px 8%; flex:1; align-content:start; }
.app-grid i{
  width:100%; aspect-ratio:1; border-radius:26%; display:block;
  background:linear-gradient(150deg,var(--c1),var(--c2));
  box-shadow:0 2px 5px #0006, inset 0 1px 0 #ffffff55;
  position:relative; overflow:hidden;
}
