    const dx = e.clientX - last.x, dy = e.clientY - last.y;
    moved += Math.hypot(dx, dy);
    last = { x: e.clientX, y: e.clientY };
    place(e.clientX, e.clientY);
    setNear(opts.hitTest ? opts.hitTest(e.clientX, e.clientY, moved) : false);
  };
  const onUp = e => {
    if (!active) return;
