262: function loadSave() {
263:   try {
264:     const raw = localStorage.getItem(SAVE_KEY);
265:     if (!raw) return false;
266:     const d = JSON.parse(raw);
267:     if (!d || typeof d.day !== 'number') return false;
268:     state.day = Math.max(1, d.day | 0);
269:     state.coins = Math.max(0, d.coins | 0);
270:     state.repSum = Math.max(0, d.repSum | 0);
271:     state.repCount = Math.max(0, d.repCount | 0);
272:     state.upgrades = Object.assign({ tools: 0, sign: 0, bench: 0 }, d.upgrades || {});
273:     state.muted = !!d.muted;
274:     state.hasSave = true;
275:     return true;
276:   } catch (e) { return false; }
277: }
