410: function nextCustomer() {
411:   if (state.jobsDone >= state.jobsTotal) { endDay(); return; }
412:   const job = state.queue[state.jobsDone % state.queue.length] || pick(JOBS);
413:   state.job = job;
414:   state.stepIndex = 0; state.stepDone = false;
415:   state.phase = 'reading'; state.timerOn = false;
416:   state.patience = 1; state.maxHearts = 3 + state.upgrades.bench; state.hearts = state.maxHearts;
417:   state.mistakes = 0; state.mood = '';
418:   state.customer = pick(CUSTOMERS.filter(c => c !== state.lastCustomer));
419:   state.lastCustomer = state.customer;
