451:   const wrap = patienceFill.parentElement;
452:   wrap.classList.toggle('low', p <= .45 && p > .2);
453:   wrap.classList.toggle('crit', p <= .2);
454:   const mood = p > .65 ? 'happy' : p > .35 ? 'ok' : p > .15 ? 'worried' : 'angry';
455:   if (force || mood !== state.mood) {
