461: /* ---------------- diagnosis ---------------- */
462: function openDiagnosis() {
463:   if (state.phase !== 'reading' || state.sheetOpen) return;
464:   audioUnlock();
465:   state.phase = 'diag';
466:   state.timerOn = false;
467:   diagHint.textContent = state.job.clue;
468:   const wrongPool = Object.keys(KITS).filter(k => k !== state.job.kit);
469:   const options = shuffle([state.job.kit, ...shuffle(wrongPool).slice(0, 2)]);
470:   kitList.innerHTML = options.map(k => {
471:     const kit = KITS[k];
472:     return `<button class="kit" data-kit="${k}">
473:       <span class="kit-ic">${icon(kit.icon)}</span>
474:       <span class="kit-txt"><b>${kit.name}</b><small>${kit.desc}</small></span>
475:       ${icon('chevron', 'chev')}
476:     </button>`;
477:   }).join('');
478:   $$('.kit', kitList).forEach(btn => btn.addEventListener('click', () => chooseKit(btn)));
479:   showSheet(diagSheet);
480:   sfx.click();
481: }
