483: function chooseKit(btn) {
484:   if (state.phase !== 'diag') return;
485:   const k = btn.dataset.kit;
486:   if (k === state.job.kit) {
487:     if (btn.classList.contains('right')) return;
488:     btn.classList.add('right');
489:     sfx.win();
490:     vibrate(20);
491:     state.phase = 'starting';
492:     setTimeout(() => {
493:       hideSheet(diagSheet);
494:       beginRepair();
495:     }, 380);
496:   } else {
497:     if (btn.classList.contains('wrong')) return;
498:     btn.classList.add('wrong');
499:     setTimeout(() => btn.classList.remove('wrong'), 480);
500:     sfx.error(); vibrate([20, 40, 20]);
501:     state.hearts = Math.max(0, state.hearts - 1);
502:     state.mistakes++;
503:     state.patience = Math.max(.02, state.patience - .07);
504:     renderHearts(); updatePatienceUI(true);
505:     diagHint.textContent = state.hearts > 0 ? 'Not quite. Look at the phone and the complaint again.' : 'Careful — the customer is losing faith.';
506:     toast('Wrong kit. That will not fix it.', 'bad');
507:   }
508: }
