510: /* ---------------- geometry / fx ---------------- */
511: const partEl = key => key === 'screen' ? screenLayer : $(`.part[data-part="${key}"]`);
512: const slotEl = key => $(`.slot-outline[data-slot="${key}"]`);
513: function insideRect(r, x, y, pad = 0) {
514:   return x >= r.left - pad && x <= r.right + pad && y >= r.top - pad && y <= r.bottom + pad;
515: }
516: function distToRect(x, y, r) {
517:   const dx = Math.max(r.left - x, 0, x - r.right);
518:   const dy = Math.max(r.top - y, 0, y - r.bottom);
519:   return Math.hypot(dx, dy);
520: }
521: function benchPoint(x, y) {
522:   const r = bench.getBoundingClientRect();
523:   return { x: x - r.left, y: y - r.top };
524: }
525: function burst(x, y, o = {}) {
526:   const { count = 8, color = '#ffd166', kind = '', spread = 46, size = 4, dur = .7 } = o;
527:   const p = benchPoint(x, y);
