662:   if (state.stepIndex >= steps.length) { finishJob(); return; }
663:   const step = steps[state.stepIndex];
664:   state.stepDone = false;
665:   renderDots(state.stepIndex, true);
666:   setDock(step.title, step.sub, step.tool, step.type === 'boot' || step.type === 'open' ? '' : 'Hint', 'secondary');
667:   setProgress(0);
668:   clearHint();
669:   state.hintTimer = setTimeout(() => showHint(step), 4200);
670:   switch (step.type) {
671:     case 'screw': setupScrews(step); break;
672:     case 'rub': setupRub(step); break;
673:     case 'open': setupOpen(step); break;
674:     case 'dragOut': setupDrag(step, true); break;
675:     case 'dragIn': setupDrag(step, false); break;
676:     case 'hold': setupHold(step); break;
677:     case 'boot': setupBoot(step); break;
