683:   cleanupStep();
684:   sfx.heart();
685:   state.stepIndex++;
686:   renderDots(state.stepIndex, true);
687:   if (state.stepIndex >= state.job.steps.length) {
688:     setTimeout(() => finishJob(), 300);
689:   } else {
690:     setTimeout(runStep, delay);
691:   }
