722: /* ---------------- rub ---------------- */
723: function rubRect(visual) {
724:   let el, pad = 8;
725:   if (visual === 'cracks' || visual === 'edges') el = screenLayer;
726:   else if (visual === 'battery') el = batteryEl;
727:   else if (visual === 'port') { el = $('.part[data-part="port"]'); pad = 22; }
728:   else if (visual === 'camera') el = $('.part[data-part="camera"]');
729:   else el = interior;
730:   let r = el.getBoundingClientRect();
731:   if (visual === 'port') {
732:     const cx = r.left + r.width / 2, cy = r.top + r.height / 2;
733:     const w = Math.max(76, r.width + pad * 2), h = 74;
734:     return { left: cx - w / 2, top: cy - h / 2, width: w, height: h, right: cx + w / 2, bottom: cy + h / 2 };
735:   }
736:   return { left: r.left - pad, top: r.top - pad, width: r.width + pad * 2, height: r.height + pad * 2, right: r.right + pad, bottom: r.bottom + pad };
737: }
738: function applyVisual(visual, p) {
739:   switch (visual) {
740:     case 'cracks': cracks.style.setProperty('--crack', (1 - p).toFixed(3)); break;
741:     case 'edges': phone.classList.add('heating'); break;
742:     case 'battery': batteryEl.style.transform = `translateY(${(-p * 4).toFixed(1)}px) rotate(${(-p * .7).toFixed(2)}deg)`; break;
743:     case 'camera': { const c = $('.part[data-part="camera"]'); c.style.transform = `translate(${(p * 2).toFixed(1)}px,${(-p * 2).toFixed(1)}px) rotate(${(p * 1.4).toFixed(2)}deg)`; break; }
744:     case 'port': lintEl.style.opacity = (1 - p).toFixed(2); break;
745:     case 'water': wetLayer.style.opacity = (1 - p).toFixed(2); break;
746:     case 'corrosion': corrosion.style.opacity = ((1 - p) * .95).toFixed(2); break;
747:   }
748: }
749: function setupRub(step) {
750:   const r = rubRect(step.visual);
751:   const br = bench.getBoundingClientRect();
752:   const zone = document.createElement('div');
753:   zone.className = 'rub-zone';
754:   zone.style.left = (r.left - br.left) + 'px';
755:   zone.style.top = (r.top - br.top) + 'px';
756:   zone.style.width = r.width + 'px';
757:   zone.style.height = r.height + 'px';
758:   bench.appendChild(zone);
759:   const kind = step.visual === 'cracks' ? 'glass' : step.visual === 'water' || step.visual === 'port' ? 'water' : step.visual === 'corrosion' ? 'dust' : '';
760:   const color = step.visual === 'cracks' ? '#dffcff' : step.visual === 'water' ? '#7fdcff' : step.visual === 'corrosion' ? '#8fbf7a' : step.visual === 'battery' ? '#cfdde0' : '#ffb066';
761:   let active = false, total = 0, last = null, acc = 0, lastTick = 0, done = false;
762:   const need = step.need || 420;
763:   if (step.visual === 'water') wetLayer.classList.add('on');
764: 
765:   const onMove = e => {
766:     if (!active || done) return;
767:     e.preventDefault();
768:     if (!last) { last = { x: e.clientX, y: e.clientY }; return; }
769:     const dx = e.clientX - last.x, dy = e.clientY - last.y;
770:     let d = Math.hypot(dx, dy);
771:     last = { x: e.clientX, y: e.clientY };
772:     if (d < .6) return;
773:     d = Math.min(d, 44);
774:     total += d; acc += d;
775:     const p = clamp(total / need, 0, 1);
776:     applyVisual(step.visual, p);
777:     setProgress(p);
778:     if (acc > 13) {
779:       acc = 0;
780:       burst(e.clientX, e.clientY, { count: step.visual === 'water' ? 2 : 2, color, kind, spread: 24, size: 3, dur: .5 });
781:       if (step.visual === 'cracks' || step.visual === 'port') sfx.crack();
782:       else sfx.heat();
783:     }
784:     const t = Math.floor(p * 6);
785:     if (t > lastTick) { lastTick = t; vibrate(4); }
786:     if (p >= 1 && !done) {
787:       done = true;
788:       active = false;
789:       cleanupStep();
790:       if (step.visual === 'cracks') { cracks.style.setProperty('--crack', 0); burstAt(screenLayer, { count: 14, color: '#dffcff', kind: 'glass', spread: 90, size: 4 }); sfx.snap(); }
791:       if (step.visual === 'edges') { phone.classList.remove('heating'); sfx.pop(); }
792:       if (step.visual === 'battery') { batteryEl.classList.add('loose'); sfx.pop(); }
793:       if (step.visual === 'water') { wetLayer.classList.remove('on'); wetLayer.style.opacity = '0'; sfx.pop(); }
794:       if (step.visual === 'corrosion') { corrosion.style.opacity = '0'; burstAt(interior, { count: 8, color: '#8fbf7a', kind: 'dust', spread: 40, size: 3 }); sfx.pop(); }
795:       if (step.visual === 'port') { lintEl.style.opacity = '0'; burstAt($('.part[data-part="port"]'), { count: 10, color: '#c9b48a', kind: 'dust', spread: 34, size: 3 }); sfx.pop(); }
796:       vibrate(20);
797:       completeStep(420);
798:     }
799:   };
800:   const onUp = () => { active = false; last = null; };
801:   const onDown = e => {
802:     if (done) return;
803:     e.preventDefault();
804:     active = true; last = { x: e.clientX, y: e.clientY };
805:     zone.classList.add('active');
806:     sfx.click();
807:   };
808:   zone.addEventListener('pointerdown', onDown);
809:   window.addEventListener('pointermove', onMove, { passive: false });
810:   window.addEventListener('pointerup', onUp);
811:   window.addEventListener('pointercancel', onUp);
812:   addCleanup(() => {
813:     zone.remove();
814:     window.removeEventListener('pointermove', onMove);
815:     window.removeEventListener('pointerup', onUp);
816:     window.removeEventListener('pointercancel', onUp);
817:     if (step.visual === 'edges') phone.classList.remove('heating');
818:   });
819: }
