834: function makeDrag(source, opts) {
835:   let ghost = null, startRect = null, active = false, moved = 0, last = null, near = false;
836:   const setNear = v => { if (near === v) return; near = v; opts.onNear && opts.onNear(v); };
837:   const place = (x, y, scale = 1.04) => {
838:     if (!ghost) return;
839:     ghost.style.transform = `translate(${x - startRect.width / 2}px, ${y - startRect.height / 2 - 4}px) scale(${scale})`;
840:   };
841:   const onDown = e => {
842:     if (active || state.stepDone) return;
843:     if (e.button && e.button > 0) return;
844:     if (e.cancelable) e.preventDefault();
845:     active = true; moved = 0; last = { x: e.clientX, y: e.clientY };
846:     startRect = source.getBoundingClientRect();
847:     ghost = source.cloneNode(true);
848:     ghost.classList.add('drag-ghost');
849:     Object.assign(ghost.style, {
850:       position: 'fixed', left: '0', top: '0', right: 'auto', bottom: 'auto', inset: 'auto',
851:       width: startRect.width + 'px', height: startRect.height + 'px', margin: '0',
852:       zIndex: '120', pointerEvents: 'none', transition: 'none', transformOrigin: 'center',
853:       visibility: 'visible', opacity: '1', filter: 'drop-shadow(0 14px 20px #0009)'
854:     });
855:     document.body.appendChild(ghost);
856:     source.style.visibility = 'hidden';
857:     document.body.classList.add('dragging');
858:     place(e.clientX, e.clientY);
859:     window.addEventListener('pointermove', onMove, { passive: false });
860:     window.addEventListener('pointerup', onUp);
861:     window.addEventListener('pointercancel', onUp);
862:     sfx.click();
863:     vibrate(6);
864:   };
865:   const onMove = e => {
866:     if (!active) return;
867:     if (e.cancelable) e.preventDefault();
868:     const dx = e.clientX - last.x, dy = e.clientY - last.y;
869:     moved += Math.hypot(dx, dy);
870:     last = { x: e.clientX, y: e.clientY };
871:     place(e.clientX, e.clientY);
872:     setNear(opts.hitTest ? opts.hitTest(e.clientX, e.clientY, moved) : false);
873:   };
874:   const onUp = e => {
875:     if (!active) return;
876:     active = false;
877:     window.removeEventListener('pointermove', onMove);
878:     window.removeEventListener('pointerup', onUp);
879:     window.removeEventListener('pointercancel', onUp);
880:     document.body.classList.remove('dragging');
881:     const success = opts.hitTest ? opts.hitTest(e.clientX, e.clientY, moved) : false;
882:     const tr = opts.targetRect ? opts.targetRect() : null;
883:     if (success) {
884:       setNear(false);
885:       if (ghost) {
886:         ghost.style.transition = 'transform .18s ease-in, opacity .18s ease-in';
887:         if (tr) {
888:           const cx = tr.left + tr.width / 2, cy = tr.top + tr.height / 2;
889:           ghost.style.transform = `translate(${cx - startRect.width / 2}px, ${cy - startRect.height / 2}px) scale(.42)`;
890:         }
891:         ghost.style.opacity = '0';
892:         const g = ghost; ghost = null;
893:         setTimeout(() => g.remove(), 210);
894:       }
895:       opts.onSuccess && opts.onSuccess();
896:     } else {
897:       setNear(false);
898:       sfx.drop();
899:       if (ghost) {
900:         ghost.style.transition = 'transform .22s cubic-bezier(.3,1.3,.5,1), opacity .2s';
901:         ghost.style.transform = `translate(${startRect.left}px, ${startRect.top}px) scale(1)`;
902:         const g = ghost; ghost = null;
903:         setTimeout(() => {
904:           g.remove();
905:           source.style.visibility = '';
906:           source.classList.remove('drag-source');
907:         }, 230);
908:       } else source.style.visibility = '';
909:       opts.onFail && opts.onFail();
910:     }
911:   };
912:   source.addEventListener('pointerdown', onDown);
913:   addCleanup(() => {
914:     source.removeEventListener('pointerdown', onDown);
915:     window.removeEventListener('pointermove', onMove);
916:     window.removeEventListener('pointerup', onUp);
917:     window.removeEventListener('pointercancel', onUp);
918:     if (ghost) { ghost.remove(); ghost = null; }
919:     source.style.visibility = '';
920:     document.body.classList.remove('dragging');
921:   });
922: }
